/**
 * Token compiler (SPEC §20.2.2). Pure: `tokens.json` in, `tokens.css` + `tokens.ts` text out, plus the
 * three build checks the spec hangs on this script — colourblind ΔE (§20.8.3), font sizes only from
 * `--t-*`, and spacing only from `--s-*` / custom properties only in tokens.css (§50.1 #14).
 *
 * It lives in `src/` (as the spec names it) and therefore imports nothing from node: the file-system
 * runner is `packages/client/scripts/tokens.ts` (`pnpm --filter @ewa/client tokens`), and
 * `test/design-system.test.ts` calls these same functions to fail CI when a generated file drifts.
 */

export interface TypeStep {
  readonly size: number;
  readonly line: number;
  readonly face: 'text' | 'display' | 'mono';
}

export interface TokenSource {
  readonly color: Readonly<Record<string, string>>;
  readonly typeColors: Readonly<Record<'default' | Colorblind, Readonly<Record<string, string>>>>;
  readonly space: Readonly<Record<string, number>>;
  readonly radius: Readonly<Record<string, number>>;
  readonly type: Readonly<Record<string, TypeStep>>;
  readonly font: Readonly<Record<'display' | 'text' | 'mono', string>>;
  readonly motion: Readonly<Record<string, number>>;
  readonly ease: Readonly<Record<string, string>>;
  readonly size: Readonly<Record<string, number>>;
  readonly shadow: Readonly<Record<string, string>>;
  readonly z: Readonly<Record<string, number>>;
}

export type Colorblind = 'deuteranopia' | 'protanopia' | 'tritanopia';
export const COLORBLIND_MODES: readonly Colorblind[] = ['deuteranopia', 'protanopia', 'tritanopia'];

/** The minimum CIELAB ΔE (CIE76) between adjacent types in TYPE_NAMES order, under each simulation (§20.8.3). */
export const MIN_ADJACENT_DELTA_E = 40;

const HEADER = 'GENERATED by src/ui/gen-tokens.ts from src/ui/tokens.json. Do not edit; run `pnpm --filter @ewa/client tokens`.';

// ---- colour maths -----------------------------------------------------------------------------------------

type Vec3 = readonly [number, number, number];

/** Machado, Oliveira & Fernandes 2009, severity 1.0, applied to linear RGB. */
const MACHADO: Readonly<Record<Colorblind, readonly Vec3[]>> = {
  protanopia: [
    [0.152286, 1.052583, -0.204868],
    [0.114503, 0.786281, 0.099216],
    [-0.003882, -0.048116, 1.051998],
  ],
  deuteranopia: [
    [0.367322, 0.860646, -0.227968],
    [0.280085, 0.672501, 0.047413],
    [-0.01182, 0.04294, 0.968881],
  ],
  tritanopia: [
    [1.255528, -0.076749, -0.178779],
    [-0.078411, 0.930809, 0.147602],
    [0.004733, 0.691367, 0.3039],
  ],
};

const clamp01 = (x: number): number => Math.min(1, Math.max(0, x));

export function hexToRgb(hex: string): Vec3 {
  const m = /^#([0-9a-f]{6})$/i.exec(hex);
  if (m === null) throw new RangeError(`not a #rrggbb colour: ${hex}`);
  const n = parseInt(m[1]!, 16);
  return [((n >> 16) & 255) / 255, ((n >> 8) & 255) / 255, (n & 255) / 255];
}

const toLinear = (c: number): number => (c <= 0.04045 ? c / 12.92 : ((c + 0.055) / 1.055) ** 2.4);

export function linearRgb(hex: string): Vec3 {
  const [r, g, b] = hexToRgb(hex);
  return [toLinear(r), toLinear(g), toLinear(b)];
}

export function simulate(hex: string, mode: Colorblind | null): Vec3 {
  const lin = linearRgb(hex);
  if (mode === null) return lin;
  const m = MACHADO[mode];
  const row = (i: number): number => clamp01(m[i]![0] * lin[0] + m[i]![1] * lin[1] + m[i]![2] * lin[2]);
  return [row(0), row(1), row(2)];
}

/** Linear sRGB (D65) → CIELAB. */
export function labOf(lin: Vec3): Vec3 {
  const [r, g, b] = lin;
  const x = (0.4124 * r + 0.3576 * g + 0.1805 * b) / 0.95047;
  const y = 0.2126 * r + 0.7152 * g + 0.0722 * b;
  const z = (0.0193 * r + 0.1192 * g + 0.9505 * b) / 1.08883;
  const f = (t: number): number => (t > 216 / 24389 ? Math.cbrt(t) : ((24389 / 27) * t + 16) / 116);
  return [116 * f(y) - 16, 500 * (f(x) - f(y)), 200 * (f(y) - f(z))];
}

export function deltaE(a: Vec3, b: Vec3): number {
  return Math.hypot(a[0] - b[0], a[1] - b[1], a[2] - b[2]);
}

/** WCAG 2.x relative luminance / contrast ratio. */
export function luminance(hex: string): number {
  const [r, g, b] = linearRgb(hex);
  return 0.2126 * r + 0.7152 * g + 0.0722 * b;
}
export function contrast(a: string, b: string): number {
  const la = luminance(a);
  const lb = luminance(b);
  return (Math.max(la, lb) + 0.05) / (Math.min(la, lb) + 0.05);
}

// ---- checks -----------------------------------------------------------------------------------------------

export interface Violation {
  readonly where: string;
  readonly message: string;
}

export function colorblindViolations(t: TokenSource): Violation[] {
  const out: Violation[] = [];
  const order = Object.keys(t.typeColors.default);
  for (const mode of COLORBLIND_MODES) {
    const pal = t.typeColors[mode];
    if (Object.keys(pal).join() !== order.join()) out.push({ where: `typeColors.${mode}`, message: 'must list the 19 types in TYPE_NAMES order' });
    for (let i = 0; i + 1 < order.length; i++) {
      const a = pal[order[i]!];
      const b = pal[order[i + 1]!];
      if (a === undefined || b === undefined) continue;
      const d = deltaE(labOf(simulate(a, mode)), labOf(simulate(b, mode)));
      if (d < MIN_ADJACENT_DELTA_E) {
        out.push({ where: `typeColors.${mode}`, message: `${order[i]}/${order[i + 1]} ΔE ${d.toFixed(1)} < ${MIN_ADJACENT_DELTA_E}` });
      }
    }
  }
  return out;
}

export interface SourceFile {
  readonly path: string;
  readonly text: string;
}

/** Strips `/* … *\/` comments so a commented-out value never counts. */
function stripComments(css: string): string {
  return css.replace(/\/\*[\s\S]*?\*\//g, '');
}

function declarations(css: string, prop: RegExp): { prop: string; value: string }[] {
  const out: { prop: string; value: string }[] = [];
  const re = /(^|[{;\s])([a-z-]+)\s*:\s*([^;{}]+)/g;
  for (let m = re.exec(css); m !== null; m = re.exec(css)) {
    const p = m[2]!;
    if (prop.test(p)) out.push({ prop: p, value: m[3]!.trim() });
  }
  return out;
}

/** §20.2.2: every `font-size` is a `--t-*` token; the `font` shorthand may only reset (`inherit`). */
export function fontSizeViolations(files: readonly SourceFile[]): Violation[] {
  const out: Violation[] = [];
  for (const f of files) {
    const css = stripComments(f.text);
    for (const d of declarations(css, /^font-size$/)) {
      if (!/^var\(--t-[a-z0-9-]+\)$/.test(d.value)) out.push({ where: f.path, message: `font-size: ${d.value} (use a --t-* token)` });
    }
    for (const d of declarations(css, /^font$/)) {
      if (d.value !== 'inherit') out.push({ where: f.path, message: `font: ${d.value} (only 'font: inherit' is allowed; size via --t-*)` });
    }
  }
  return out;
}

const SPACING_PROP = /^(margin|padding|gap|row-gap|column-gap)(-(top|right|bottom|left|inline|block|inline-start|inline-end|block-start|block-end))?$/;

/** §20.2.2: margin/padding/gap values are `--s-*` tokens (or 0 / auto); no raw lengths. */
export function spacingViolations(files: readonly SourceFile[]): Violation[] {
  const out: Violation[] = [];
  for (const f of files) {
    const css = stripComments(f.text);
    for (const d of declarations(css, SPACING_PROP)) {
      const rawLength = /(^|[\s(,*+/-])-?\d*\.?\d+(px|rem|em|%|vh|vw|ch)\b/.test(d.value);
      const foreignVar = [...d.value.matchAll(/var\((--[a-z0-9-]+)/g)].some((m) => !/^--s-\d$/.test(m[1]!));
      if (rawLength || foreignVar) out.push({ where: f.path, message: `${d.prop}: ${d.value} (use --s-* tokens)` });
    }
  }
  return out;
}

/** §50.1 #14: tokens.css is the only file declaring CSS custom properties. */
export function customPropertyViolations(files: readonly SourceFile[]): Violation[] {
  const out: Violation[] = [];
  for (const f of files) {
    if (f.path.endsWith('/tokens.css')) continue;
    const css = stripComments(f.text);
    const re = /(^|[{;\s])(--[a-z0-9-]+)\s*:/g;
    for (let m = re.exec(css); m !== null; m = re.exec(css)) out.push({ where: f.path, message: `declares ${m[2]} (custom properties live in tokens.json)` });
  }
  return out;
}

// ---- emitters ---------------------------------------------------------------------------------------------

const slug = (typeName: string): string => typeName.toLowerCase();

/** Readable ink over a type colour: whichever of bg-0 / text-hi contrasts more. */
export function inkFor(hex: string, dark: string, light: string): string {
  return contrast(hex, dark) >= contrast(hex, light) ? dark : light;
}

const rem = (px: number): string => `calc(${px} / 16 * 1rem * var(--ui-scale))`;

export function buildCss(t: TokenSource): string {
  const dark = t.color['bg-0']!;
  const light = t.color['text-hi']!;
  const lines: string[] = [`/* ${HEADER} */`, ':root {', '  --ui-scale: 1;'];
  const decl = (name: string, value: string | number): void => {
    lines.push(`  --${name}: ${value};`);
  };
  for (const [k, v] of Object.entries(t.color)) decl(k, v);
  for (const [k, v] of Object.entries(t.typeColors.default)) {
    decl(`type-${slug(k)}`, v);
    decl(`type-${slug(k)}-ink`, inkFor(v, dark, light));
  }
  for (const [k, v] of Object.entries(t.space)) decl(k, `${v}px`);
  for (const [k, v] of Object.entries(t.radius)) decl(k, `${v}px`);
  for (const [k, v] of Object.entries(t.type)) {
    decl(k, rem(v.size));
    decl(k.replace(/^t-/, 'lh-'), rem(v.line));
  }
  for (const [k, v] of Object.entries(t.font)) decl(`face-${k}`, v);
  for (const [k, v] of Object.entries(t.motion)) decl(k, `${v}ms`);
  for (const [k, v] of Object.entries(t.ease)) decl(k, v);
  for (const [k, v] of Object.entries(t.size)) decl(k, `${v}px`);
  for (const [k, v] of Object.entries(t.shadow)) decl(k, v);
  for (const [k, v] of Object.entries(t.z)) decl(k, v);
  lines.push('}', '');
  lines.push('/* §20.2.2: every --motion-* is 0ms under effective reduced motion */', ':root[data-reduced="1"] {');
  for (const k of Object.keys(t.motion)) decl(k, '0ms');
  lines.push('}', '');
  for (const mode of COLORBLIND_MODES) {
    lines.push(`/* §20.8.3 ${mode} */`, `:root[data-cb="${mode}"] {`);
    for (const [k, v] of Object.entries(t.typeColors[mode])) {
      decl(`type-${slug(k)}`, v);
      decl(`type-${slug(k)}-ink`, inkFor(v, dark, light));
    }
    lines.push('}', '');
  }
  lines.push('/* data-type="<TypeName>" exposes --tc / --tc-ink to any component (TypeBadge, cards, beacons) */');
  for (const k of Object.keys(t.typeColors.default)) {
    lines.push(`[data-type="${k}"] { --tc: var(--type-${slug(k)}); --tc-ink: var(--type-${slug(k)}-ink); }`);
  }
  return `${lines.join('\n')}\n`;
}

const json = (v: unknown): string => JSON.stringify(v, null, 2);

export function buildTs(t: TokenSource): string {
  return [
    `// ${HEADER}`,
    '// Numbers for the canvas HUD and the battle timeline (SPEC §20.2.2 / §20.6); CSS reads tokens.css.',
    '',
    `export const COLOR = ${json(t.color)} as const;`,
    '',
    `export const TYPE_COLORS = ${json(t.typeColors)} as const;`,
    '',
    `export const SPACE = ${json(t.space)} as const;`,
    '',
    `export const RADIUS = ${json(t.radius)} as const;`,
    '',
    `export const TYPE_SCALE = ${json(t.type)} as const;`,
    '',
    `export const FONT = ${json(t.font)} as const;`,
    '',
    `export const MOTION_MS = ${json(t.motion)} as const;`,
    '',
    `export const EASE = ${json(t.ease)} as const;`,
    '',
    `export const SIZE = ${json(t.size)} as const;`,
    '',
    `export const Z = ${json(t.z)} as const;`,
    '',
    'export type ColorToken = keyof typeof COLOR;',
    'export type SpaceToken = keyof typeof SPACE;',
    'export type TypeToken = keyof typeof TYPE_SCALE;',
    '',
  ].join('\n');
}

export interface TokenBuild {
  readonly css: string;
  readonly ts: string;
  readonly violations: readonly Violation[];
}

/** Everything the runner writes and everything that fails the build. */
export function buildTokenFiles(t: TokenSource, moduleCss: readonly SourceFile[] = []): TokenBuild {
  return {
    css: buildCss(t),
    ts: buildTs(t),
    violations: [
      ...colorblindViolations(t),
      ...fontSizeViolations(moduleCss),
      ...spacingViolations(moduleCss),
      ...customPropertyViolations(moduleCss),
    ],
  };
}
